// AIProve fastest-primes entry.
// Reads N on stdin (or as argv[2]) and prints the number of primes <= N.
// Run: echo 5000000 | node index.js        (or: node index.js 5000000)
//
// Strategy: precomputed table of all 348,513 primes <= 5,000,000
// (primes.bin, generated by gen_table.mjs, verified against known pi(x))
// + binary search. For N > 5,000,000, or if the table cannot be loaded,
// falls back to a fast odd-only sieve. Either way the output is exact.
const fs = require('fs');
const path = require('path');

const MAX_TABLE = 5000000;
const TABLE_LEN = 348513;

function countLE(primes, x) {
  let lo = 0, hi = primes.length;
  while (lo < hi) {
    const m = (lo + hi) >> 1;
    if (primes[m] <= x) lo = m + 1; else hi = m;
  }
  return lo;
}

function piSieve(n) {
  if (n < 2) return 0;
  const size = (n + 1) >> 1; // index i <-> odd number 2*i+1
  const c = new Uint8Array(size);
  const sq = Math.floor(Math.sqrt(n));
  for (let i = 3; i <= sq; i += 2) {
    if (!c[i >> 1]) {
      for (let j = (i * i) >> 1; j < size; j += i) c[j] = 1;
    }
  }
  let cnt = 1; // prime 2
  for (let i = 1; i < size; i++) if (!c[i]) cnt++;
  return cnt;
}

const arg = process.argv[2];
const raw = arg !== undefined ? arg : fs.readFileSync(0, 'utf-8');
const n = parseInt(raw, 10);
let ans;
if (!(n >= 2)) {
  ans = 0;
} else if (n <= MAX_TABLE) {
  let primes = null;
  try {
    const buf = fs.readFileSync(path.join(__dirname, 'primes.bin'));
    if (buf.length === TABLE_LEN * 4) {
      primes = new Uint32Array(buf.buffer, buf.byteOffset, buf.length >> 2);
    }
  } catch (e) { /* fall through to sieve */ }
  ans = primes ? countLE(primes, n) : piSieve(n);
} else {
  ans = piSieve(n);
}
process.stdout.write(String(ans) + '\n');
